<?php declare(strict_types=1);namespace App\Interface\Http\Arena;use App\Application\Arena\Service\AnswerDuelService;use App\Application\Identity\Service\AuthService;use App\Infrastructure\Http\ApiResponseFactory;use App\Infrastructure\Persistence\Doctrine\Arena\DoctrineDuelAnswerVerifier;use App\Infrastructure\Persistence\Doctrine\Arena\DoctrineDuelRepository;use App\Infrastructure\Persistence\Doctrine\DoctrineEntityManagerFactory;use App\Infrastructure\Persistence\Doctrine\DoctrineTransactionManager;use App\Interface\Http\Arena\Controller\ArenaAnswerController;use Psr\Http\Message\ResponseInterface;use Psr\Http\Message\ServerRequestInterface;use Slim\App;final class ArenaAnswerRouteRegistrar{public function __construct(private readonly ApiResponseFactory $responses,private readonly AuthService $auth){}public function register(App $app):void{$em=DoctrineEntityManagerFactory::create();$c=new ArenaAnswerController($this->auth,new AnswerDuelService(new DoctrineDuelRepository($em),new DoctrineDuelAnswerVerifier($em),new DoctrineTransactionManager($em)),$this->responses);$app->post('/v1/arena/duels/{id}/answers',function(ServerRequestInterface $r,ResponseInterface $s,array $a)use($c):ResponseInterface{try{$p=json_decode((string)$r->getBody(),true,512,JSON_THROW_ON_ERROR);$option=$p['option_id']??null;if(!is_string($option)||$option==='')throw new \InvalidArgumentException();return$c->answer($r,$s,(string)$a['id'],$option);}catch(\Throwable){return$this->responses->problem($s,'VALIDATION_FAILED','Alternativa inválida.',422,(string)$r->getAttribute('request_id'));}});}}
